pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blockTimestamp, uint256 blockNumber) public {
        vm.assume(blockTimestamp > 0);
        vm.assume(blockNumber % 15 == 0);

        address caller = address(0x1234);
        vm.deal(caller, 10 ether);

        vm.warp(blockTimestamp);
        vm.roll(blockNumber);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        assertTrue(address(c).balance == 0);
    }
}
